const CACHE="mono-mock-v60";const ASSETS=["./launch.js?v=60","./apple-touch-icon.png?v=60","./icon-192.png?v=60","./auth-gate.js?v=60","./auth.css?v=60","./cabinets.js?v=60","./assets/reference/limits-sticker-hq.png","./assets/reference/market-eyes-hq.png","./assets/reference/market-owl-hq.png","./sharp-icons.js?v=60","./bank-detail.js?v=60","./bank-detail.css?v=60","./assets/reference/transfer-pattern.svg","./icon-catalog.js?v=60","./mobile-stability.js?v=60","./mobile-stability.css?v=60","./pull-refresh.js?v=60","./hosted-storage.js?v=60","./card-stable.js?v=60","./card-stable.css?v=60","./profile-pwa.js?v=60","./profile-pwa.css?v=60","./history-glass.js?v=60","./history-glass.css?v=60","./faithful.css?v=60","./faithful-motion.js?v=60","./faithful-entry.js?v=60","./receipt-links.js?v=60","./native-reference.js?v=60","./native-reference.css?v=60","./reference-fidelity.js?v=60","./reference-fidelity.css?v=60","./continuity.js?v=60","./continuity.css?v=60","./motion.js?v=60","./motion.css?v=60","./recording.js?v=60","./recording.css?v=60","./interactions.js?v=60","./interactions.css?v=60","./surfaces.js?v=60","./surfaces.css?v=60","./refinement.css?v=60","./refinement.js?v=60","./reference.css?v=60","./experience.js?v=60","./style.css?v=60","./app.js?v=60","./manifest.json","./icon.svg","./icon.png","./pwa-runtime.js?v=60","./pwa-runtime.css?v=60","./admin-manifest.json"];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('mono-mock-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/'))return;
 if(request.mode==='navigate'){event.respondWith(fetch(new Request(request,{cache:'no-store'})).catch(()=>new Response('<!doctype html><meta name="viewport" content="width=device-width"><style>html{background:#161616;color:white;font:18px system-ui;padding:24px}</style>Потрібне з’єднання з інтернетом. Відкрийте застосунок повторно після підключення.',{headers:{'Content-Type':'text/html; charset=utf-8'}})));return}
 event.respondWith(fetch(request).then(response=>{if(response.ok&&url.pathname.startsWith('/assets/')){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(request,copy)))}return response}).catch(()=>caches.match(request).then(cached=>cached||Response.error())))
});
